--- /dev/null
+++ b/Sources/SwiftML/Core/CPUWorkspaceTrial.swift
@@ -0,0 +1,110 @@
+import Foundation
+import Darwin
+import Accelerate
+
+public enum CPUWorkspaceTrialError: Error, Sendable { case capacity }
+
+// THROWAWAY: one exclusive, bounded CPU workspace for a sequential-fit experiment.
+// This is not a production API or a process-wide memory budget.
+public enum CPUWorkspaceTrial {
+    private static let storage = Storage()
+    private final class Storage: @unchecked Sendable {
+        let lock = NSLock()
+        var enabled = false
+        var adaptive = false
+        var plannedCount = 0
+        var allocatedCount = 0
+        var pointer: UnsafeMutablePointer<Double>?
+        let capacity = 32 * 1024 * 1024 / MemoryLayout<Double>.stride
+        var allocations = 0
+        var uses = 0
+        var active = 0
+    }
+    public static var isEnabled: Bool {
+        storage.lock.lock(); defer { storage.lock.unlock() }
+        return storage.enabled
+    }
+    public static func begin(plannedBytes: Int = 0) {
+        storage.lock.lock(); defer { storage.lock.unlock() }
+        precondition(storage.pointer == nil && !storage.enabled)
+        precondition(plannedBytes >= 0 && plannedBytes <= storage.capacity * 8 && plannedBytes % Int(getpagesize()) == 0)
+        storage.plannedCount = plannedBytes / 8
+        storage.allocations = 0; storage.uses = 0; storage.enabled = true
+        storage.adaptive = ProcessInfo.processInfo.environment["CPU_WORKSPACE_SIZING"] == "adaptive"
+    }
+    public static func snapshot() -> [String: Int] {
+        storage.lock.lock(); defer { storage.lock.unlock() }
+        return ["capacity_bytes": storage.capacity * 8,
+                "owned_bytes": storage.allocatedCount * 8, "planned_bytes": storage.plannedCount * 8,
+                "allocations": storage.allocations, "uses": storage.uses, "active": storage.active]
+    }
+    public static func end() {
+        storage.lock.lock(); defer { storage.lock.unlock() }
+        precondition(storage.active == 0)
+        storage.pointer?.deinitialize(count: storage.allocatedCount)
+        storage.pointer?.deallocate(); storage.pointer = nil; storage.allocatedCount = 0; storage.enabled = false
+    }
+    static func withBuffers(matrixCount: Int, rhsCount: Int, scratchCount: Int = 1,
+        _ body: (UnsafeMutablePointer<Double>, UnsafeMutablePointer<Double>, UnsafeMutablePointer<Double>, Int) throws -> Void) throws {
+        storage.lock.lock(); defer { storage.lock.unlock() }
+        guard storage.enabled, matrixCount > 0, rhsCount > 0,
+              matrixCount <= storage.capacity, rhsCount < storage.capacity - matrixCount, scratchCount > 0,
+              scratchCount <= storage.capacity - matrixCount - rhsCount else {
+            throw CPUWorkspaceTrialError.capacity
+        }
+        let pageCount = Int(getpagesize()) / MemoryLayout<Double>.stride
+        let needed = matrixCount + rhsCount + scratchCount
+        guard storage.plannedCount == 0 || needed <= storage.plannedCount else { throw CPUWorkspaceTrialError.capacity }
+        let desired = storage.plannedCount > 0 ? storage.plannedCount : storage.adaptive ? ((needed + pageCount - 1) / pageCount) * pageCount : storage.capacity
+        if storage.allocatedCount < desired {
+            storage.pointer?.deinitialize(count: storage.allocatedCount)
+            storage.pointer?.deallocate()
+            storage.pointer = .allocate(capacity: desired)
+            storage.pointer!.initialize(repeating: 0, count: desired)
+            storage.allocatedCount = desired
+            storage.allocations += 1
+        }
+        storage.active += 1
+        defer { storage.active -= 1 }
+        let pointer = storage.pointer!
+        try body(pointer, pointer + matrixCount, pointer + matrixCount + rhsCount,
+                 storage.allocatedCount - matrixCount - rhsCount)
+        storage.uses += 1
+    }
+    public static func requiredBytes(rows: Int, width: Int) throws -> Int {
+        let limit = 32 * 1024 * 1024 / 8
+        guard rows > width, width > 0, width < Int32.max, rows <= Int32.max,
+              rows <= limit / (width + 1) else { throw CPUWorkspaceTrialError.capacity }
+        var trans = Int8(78), m = Int32(rows), n = Int32(width + 1), nrhs = Int32(1)
+        var lda = m, ldb = m, lwork = Int32(-1), info = Int32(0)
+        var a = 0.0, b = 0.0, query = 0.0
+        dgels_(&trans, &m, &n, &nrhs, &a, &lda, &b, &ldb, &query, &lwork, &info)
+        guard info == 0, query.isFinite, query > 0, query <= Double(limit) else { throw CPUWorkspaceTrialError.capacity }
+        let needed = rows * (width + 1) + rows + Int(query)
+        let pageCount = Int(getpagesize()) / 8
+        let rounded = ((needed + pageCount - 1) / pageCount) * pageCount
+        guard rounded <= limit else { throw CPUWorkspaceTrialError.capacity }
+        return rounded * 8
+    }
+    public static func check() throws {
+        enum Sentinel: Error { case expected }
+        begin(); defer { end() }
+        do {
+            try withBuffers(matrixCount: 16, rhsCount: 8) { a, b, _, _ in
+                a[0] = 17; b[0] = 23; throw Sentinel.expected
+            }
+            preconditionFailure("Expected throw")
+        } catch Sentinel.expected {}
+        precondition(snapshot()["active"] == 0)
+        try withBuffers(matrixCount: 16, rhsCount: 8) { a, b, _, _ in
+            precondition(a[0] == 17 && b[0] == 23)
+        }
+        do {
+            try withBuffers(matrixCount: 32 * 1024 * 1024 / 8, rhsCount: 1) { _, _, _, _ in
+                preconditionFailure("Over-capacity body executed")
+            }
+            preconditionFailure("Over-capacity request accepted")
+        } catch is CPUWorkspaceTrialError {}
+        precondition(snapshot()["allocations"] == 1 && snapshot()["uses"] == 1 && snapshot()["active"] == 0)
+    }
+}
